#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <time.h>
#include <openssl/sha.h>
#include <openssl/rand.h>

#define SESSION_DIR "/var/lib/app/sessions"
#define MAX_SESSION_ID_LEN 64
#define SESSION_DATA_MAX 4096
#define SESSION_TIMEOUT 3600
#define INTEGRITY_HASH_LEN SHA256_DIGEST_LENGTH

typedef struct {
    char session_id[MAX_SESSION_ID_LEN + 1];
    char username[128];
    int privilege_level;
    time_t created_at;
    time_t last_access;
    unsigned char integrity[INTEGRITY_HASH_LEN];
} SessionData;

/* Validate session ID contains only safe characters */
static int validate_session_id(const char *sid) {
    if (!sid) return 0;
    size_t len = strlen(sid);
    if (len == 0 || len > MAX_SESSION_ID_LEN) return 0;
    for (size_t i = 0; i < len; i++) {
        char c = sid[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '-' || c == '_')) {
            return 0;
        }
    }
    /* Prevent path traversal */
    if (strstr(sid, "..") != NULL) return 0;
    return 1;
}

/* Compute HMAC-like integrity hash over session fields */
static void compute_integrity(const SessionData *s, const unsigned char *key,
                              size_t key_len, unsigned char *out) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, key, key_len);
    SHA256_Update(&ctx, s->session_id, strlen(s->session_id));
    SHA256_Update(&ctx, s->username, strlen(s->username));
    SHA256_Update(&ctx, &s->privilege_level, sizeof(s->privilege_level));
    SHA256_Update(&ctx, &s->created_at, sizeof(s->created_at));
    SHA256_Update(&ctx, &s->last_access, sizeof(s->last_access));
    SHA256_Final(out, &ctx);
}

static unsigned char g_integrity_key[32];
static int g_key_initialized = 0;

static int ensure_key_loaded(void) {
    if (g_key_initialized) return 1;
    int fd = open("/var/lib/app/session_key", O_RDONLY);
    if (fd < 0) return 0;
    ssize_t n = read(fd, g_integrity_key, sizeof(g_integrity_key));
    close(fd);
    if (n != sizeof(g_integrity_key)) return 0;
    g_key_initialized = 1;
    return 1;
}

/*
 * Load and validate a session from disk.
 */
int load_session(const char *session_id, SessionData *out) {
    if (!validate_session_id(session_id)) {
        return -1;
    }
    if (!ensure_key_loaded()) {
        return -1;
    }

    char path[256];
    int written = snprintf(path, sizeof(path), "%s/%s.sess", SESSION_DIR, session_id);
    if (written < 0 || (size_t)written >= sizeof(path)) {
        return -1;
    }

    /* Open with O_NOFOLLOW to prevent symlink attacks */
    int fd = open(path, O_RDONLY | O_NOFOLLOW);
    if (fd < 0) {
        return -1;
    }

    /* Validate file size matches expected session structure size */
    struct stat st;
    if (fstat(fd, &st) != 0) {
        close(fd);
        return -1;
    }

    size_t expected_size = sizeof(SessionData);
    if (st.st_size < 0 || (size_t)st.st_size != expected_size) {
        close(fd);
        return -1;
    }

    /* Read session data */
    SessionData tmp;
    ssize_t bytes_read = read(fd, &tmp, sizeof(SessionData));
    close(fd);

    if (bytes_read != (ssize_t)sizeof(SessionData)) {
        return -1;
    }

    /* Verify integrity hash */
    unsigned char computed_hash[INTEGRITY_HASH_LEN];
    compute_integrity(&tmp, g_integrity_key, sizeof(g_integrity_key), computed_hash);

    /* Constant-time comparison to prevent timing attacks */
    unsigned int diff = 0;
    for (int i = 0; i < INTEGRITY_HASH_LEN; i++) {
        diff |= computed_hash[i] ^ tmp.integrity[i];
    }
    if (diff != 0) {
        return -1;
    }

    /* Check session timeout */
    time_t now = time(NULL);
    if (now - tmp.last_access > SESSION_TIMEOUT) {
        char del_path[256];
        snprintf(del_path, sizeof(del_path), "%s/%s.sess", SESSION_DIR, session_id);
        unlink(del_path);
        return -1;
    }

    memcpy(out, &tmp, sizeof(SessionData));
    return 0;
}

/*
 * Elevate session privileges after re-authentication.
 */
int elevate_session(const char *session_id, int new_level) {
    if (!validate_session_id(session_id)) return -1;
    if (!ensure_key_loaded()) return -1;
    if (new_level < 0 || new_level > 3) return -1;

    SessionData sess;
    if (load_session(session_id, &sess) != 0) {
        return -1;
    }

    /* Update privilege level */
    sess.privilege_level = new_level;
    sess.last_access = time(NULL);

    /* Recompute integrity */
    compute_integrity(&sess, g_integrity_key, sizeof(g_integrity_key), sess.integrity);

    /* Write back atomically using rename */
    char tmp_path[256], final_path[256];
    snprintf(final_path, sizeof(final_path), "%s/%s.sess", SESSION_DIR, session_id);
    snprintf(tmp_path, sizeof(tmp_path), "%s/.tmp_%s.sess", SESSION_DIR, session_id);

    int fd = open(tmp_path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd < 0) return -1;

    ssize_t w = write(fd, &sess, sizeof(SessionData));
    if (w != (ssize_t)sizeof(SessionData)) {
        close(fd);
        unlink(tmp_path);
        return -1;
    }
    fsync(fd);
    close(fd);

    if (rename(tmp_path, final_path) != 0) {
        unlink(tmp_path);
        return -1;
    }

    return 0;
}

/*
 * Check if user has required privilege for an action.
 * Loads session fresh from disk to prevent stale privilege data.
 */
int check_privilege(const char *session_id, int required_level) {
    SessionData sess;
    if (load_session(session_id, &sess) != 0) {
        return 0; /* deny on error */
    }
    return sess.privilege_level >= required_level;
}

/*
 * Admin action: delete another user's data.
 * Requires privilege level 3.
 */
int admin_delete_user_data(const char *admin_session_id, const char *target_user) {
    /* Verify admin has sufficient privileges */
    if (!check_privilege(admin_session_id, 3)) {
        return -1;
    }

    /* Re-load and re-verify to minimize TOCTOU window */
    SessionData admin_sess;
    if (load_session(admin_session_id, &admin_sess) != 0) {
        return -1;
    }

    if (admin_sess.privilege_level < 3) {
        return -1;
    }

    /* Validate target_user strictly */
    if (!target_user || strlen(target_user) == 0 || strlen(target_user) > 127) {
        return -1;
    }
    for (size_t i = 0; i < strlen(target_user); i++) {
        char c = target_user[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_')) {
            return -1;
        }
    }

    /* Safely delete user data directory using direct syscalls, not system() */
    char user_data_path[256];
    int pn = snprintf(user_data_path, sizeof(user_data_path),
             "/var/lib/app/userdata/%s", target_user);
    if (pn < 0 || (size_t)pn >= sizeof(user_data_path)) return -1;

    /* Use nftw or direct unlink - here we just remove the directory entry */
    /* For this implementation, we only delete the user's session file */
    char sess_path[256];
    int sn = snprintf(sess_path, sizeof(sess_path),
             "%s/%s.sess", SESSION_DIR, target_user);
    if (sn < 0 || (size_t)sn >= sizeof(sess_path)) return -1;

    /* Verify the path is under our expected directory before deletion */
    if (strncmp(sess_path, SESSION_DIR, strlen(SESSION_DIR)) != 0) {
        return -1;
    }

    unlink(sess_path);
    return 0;
}
